def build(p):
    import cadquery as cq
    cx = p['R_station']
    px, pz = cx + p['pivot_r'] * math.cos(math.radians(-60)), -p['pivot_r'] * math.sin(math.radians(-60))
    post = cq.Workplane("XZ").circle(45).extrude(-p['y']).translate((px, p['y'], pz))
    ang = math.atan2(-(0 - pz), cx - px)
    arm = cq.Workplane("XY").box(p['arm_len'], 40, p['w']).translate((p['arm_len'] / 2, 0, 0)).rotate((0, 0, 0), (0, 1, 0), math.degrees(ang)).translate((px, p['y'] - 20, pz))
    return post.union(arm)
